import re,pandas as pd,numpy as np
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor,RandomForestRegressor,HistGradientBoostingRegressor,RandomForestRegressor
from sklearn.neighbors import KNeighborsRegressor
D=pd.read_csv('/work/b3_supercon_data.csv'); pat=re.compile(r'([A-Z][a-z]?)([0-9]*\.?[0-9]*)')
def parse(s):
 d={}
 for e,n in pat.findall(s): d[e]=d.get(e,0)+(float(n) if n else 1.)
 t=sum(d.values()); return {e:v/t for e,v in d.items()}
P=[parse(s) for s in D.composition]; E=sorted(set().union(*P)); ei={e:i for i,e in enumerate(E)}
X=np.zeros((len(P),len(E)))
for i,d in enumerate(P):
 for e,v in d.items():X[i,ei[e]]=v
# collapse exact vectors
keys=[tuple(np.round(x,12)) for x in X]; groups={}
for i,k in enumerate(keys):groups.setdefault(k,[]).append(i)
Xu=np.array([X[v[0]] for v in groups.values()]); yu=np.array([D.target.iloc[v].mean() for v in groups.values()])
mods=[ExtraTreesRegressor(n_estimators=1000,min_samples_leaf=1,max_features=1.0,random_state=1,n_jobs=-1),ExtraTreesRegressor(n_estimators=1000,min_samples_leaf=2,max_features=1.0,random_state=2,n_jobs=-1),RandomForestRegressor(n_estimators=1000,min_samples_leaf=1,max_features=1.0,random_state=3,n_jobs=-1)]
for m in mods:m.fit(Xu,yu)
kn=KNeighborsRegressor(n_neighbors=5,weights='distance').fit(np.sqrt(Xu),yu)
def vec(d):
 x=np.zeros(len(E)); s=sum(d.values())
 for e,v in d.items():x[ei[e]]=v/s
 return x
def pred(x):return np.array([*(m.predict(x[None])[0] for m in mods),kn.predict(np.sqrt(x)[None])[0]])
def stress(name,d):
 x=vec(d); ps=[('nom',pred(x))]
 for e in d:
  for f in [.95,1.05]:
   dd=d.copy();dd[e]*=f;xx=vec(dd);ps.append((f'{e}{f:+.2f}',pred(xx)))
 means=np.array([p.mean() for _,p in ps]); cons=np.array([p.mean()-p.std() for _,p in ps]); w=np.argmin(means);c=np.argmin(cons)
 print('\n',name, {e:round(x[ei[e]],9) for e in d})
 print('nom models',np.round(ps[0][1],2),'mean',round(means[0],2),'minusSD',round(cons[0],2))
 print('worst mean',ps[w][0],round(means[w],2),np.round(ps[w][1],2),'drop',round(means[0]-means[w],2))
 print('worst mean-SD',ps[c][0],round(cons[c],2),np.round(ps[c][1],2))
 # nearest Hellinger
 dist=np.linalg.norm(np.sqrt(Xu)-np.sqrt(x),axis=1)/np.sqrt(2)
 for ix in np.argsort(dist)[:5]:
  orig=list(groups.values())[ix]
  print(' near',round(dist[ix],4),round(yu[ix],2),D.composition.iloc[orig[0]])

stress('YBCO6.90',{'Y':1,'Ba':2,'Cu':3,'O':6.9})
stress('PbBi-agent',{'Bi':1.35,'Pb':.843,'Sr':2.05,'Ca':1.085,'Cu':1.917,'O':8})
stress('BiPb2212 midpoint',{'Bi':1.5,'Pb':.5,'Sr':2,'Ca':1,'Cu':2,'O':8})
stress('Bi2223 conventional',{'Bi':2,'Sr':2,'Ca':2,'Cu':3,'O':10})
stress('CaSr direct',{'Ca':.285,'Sr':.665,'Cu':1,'O':2})
stress('Hg-free backbone',{'Ba':2,'Ca':2,'Cu':3,'O':8})
