# Stress the proposed normalized vector without closure as a sensitivity check.
import re,pandas as pd,numpy as np
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor
from sklearn.neighbors import KNeighborsRegressor
D=pd.read_csv('/work/b3_supercon_data.csv'); pat=re.compile(r'([A-Z][a-z]?)([0-9]*\.?[0-9]*)')
def parse(s):
 d={}
 for e,n in pat.findall(s):d[e]=d.get(e,0)+(float(n) if n else 1)
 z=sum(d.values());return {e:v/z for e,v in d.items()}
P=[parse(s) for s in D.composition]; E=sorted(set().union(*P)); I={e:i for i,e in enumerate(E)}; X=np.zeros((300,len(E)))
for r,d in enumerate(P):
 for e,v in d.items():X[r,I[e]]=v
G={}
for r,x in enumerate(X):G.setdefault(tuple(np.round(x,12)),[]).append(r)
X=np.array([X[v[0]] for v in G.values()]); y=np.array([D.target.iloc[v].mean() for v in G.values()])
M=[ExtraTreesRegressor(n_estimators=1000,min_samples_leaf=1,random_state=1,n_jobs=-1),ExtraTreesRegressor(n_estimators=1000,min_samples_leaf=2,random_state=2,n_jobs=-1),RandomForestRegressor(n_estimators=1000,random_state=3,n_jobs=-1)]
for m in M:m.fit(X,y)
K=KNeighborsRegressor(5,weights='distance').fit(np.sqrt(X),y)
d={'O':.52475546,'Cu':.12571329,'Sr':.13448298,'Ca':.07118582,'Bi':.08856756,'Pb':.05529489};x=np.zeros(len(E))
for e,v in d.items():x[I[e]]=v
def p(x):return np.array([*(m.predict(x[None])[0] for m in M),K.predict(np.sqrt(np.clip(x,0,None))[None])[0]])
for e in d:
 for f in [.95,1.05]:
  q=x.copy();q[I[e]]*=f;a=p(q);print(e,f,round(a.mean(),3),round(a.std(),3),np.round(a,2))
print('nom',p(x),p(x).mean())
